(* [comment removed for export] *)
Definition dbp_seg2_post (sp gp tp a0 a1 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rav s0v s1v s2v : word) (OPT ec lo : Z) (j0 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (OPT, OPT + 24); (ec, ec + 24)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' OPT [C1 (b8 1); CB 7 (skipn 1 j0); C8 a0; C8 a1]
    /\ rw_cells rsegs m' ec (ErrCodeCells EC_clear).

Lemma dbp_seg2 : forall (OPT ec lo : Z) (rav s0v s1v s2v e0 e1 e2 : word) (fj j0 j1 j2 : list byte)
    sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 ra
    (F : bvmap 5 word) fc (m : mem),
  rw_cells rsegs m (bv_unsigned sp + -64) (dbp_frame fj s2v s1v s0v rav) ->
  rw_cells rsegs m OPT [CB 8 j0; CB 8 j1; CB 8 j2] -> OPT mod 8 = 0 ->
  rw_cells rsegs m ec [C8 e0; C8 e1; C8 e2] -> ec mod 8 = 0 ->
  stk rsegs m lo (bv_unsigned sp + -64) -> lo + 64 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp <= OPT -> bv_unsigned sp <= ec -> (OPT + 24 <= ec \/ ec + 24 <= OPT) ->
  bv_unsigned rav mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (dbp_seg2_post sp gp tp a0 a1 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc rav s0v s1v s2v OPT ec lo j0 m)
    (MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (Z_to_bv 64 ec) (Z_to_bv 64 OPT) a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 DBP_RET1) fc None m (seg_rom rsegs)).
