(* [comment removed for export] *)
(* [comment removed for export] *)
Section CLOSED.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Lemma fb_prepare_spec_closed : fb_prepare_stmt H.
  Proof. exact (fb_prepare_spec H HH memmove_le_spec). Qed.

  Lemma dbp_fb_spec_closed : dbp_fb_stmt H.
  Proof. exact (dbp_fb_spec H HH memmove_le_spec). Qed.

  (* [comment removed for export] *)
  Lemma fb_prepare_rel_empty : forall s LB m n LB' FB',
    hs_RHEAP H s LB m -> 0 <= n -> fb_prepare_rel H LB FB_empty n LB' FB' ->
    (n = 0 /\ FB' = FB_empty /\ LB' = LB)
    \/ (1 <= n /\ exists p' A', rblock_range A' n /\ FB' = mkFB A' A' A' (A' + n) (A' + n) /\ LB' = (p', A', n) :: LB).
  Proof.
    intros s LB m n LB' FB' HP N0 REL. unfold fb_prepare_rel, fb_prep_inplace, fb_prep_slide, fb_prep_small, fb_prep_grow, fb_newsize, fb_cap, fb_size in REL.
    cbn [fb_begin fb_in fb_out fb_last fb_end FB_empty] in REL.
    replace (0 - 0 - (0 - 0)) with 0 in REL by lia. replace (0 - 0) with 0 in REL by lia.
    replace (Z.max (2 * 0) (0 + n)) with n in REL by lia. rewrite !Z.add_0_l, ?orb_diag in REL.
    destruct (Z.leb_spec0 n 0) as [L|L].
    - left. destruct REL as [-> ->]. split; [lia|]. split; [| reflexivity]. destruct (fb_prep_inplace FB_empty n); unfold FB_empty; f_equal; lia.
    - right. split; [lia|]. destruct REL as (p' & A' & BR & -> & CASES).
      exists p', A'. split; [exact BR|]. split; [f_equal; lia|].
      destruct CASES as [[_ E] | (p & IN & _)]; [exact E | exfalso].
      destruct (hh_blocks H HH _ _ _ _ HP IN) as (R1 & _ & R3 & _). cbn in R1, R3. lia.
  Qed.
End CLOSED.

(* [comment removed for export] *)
Lemma fb_newsize_bound : forall FB n, 0 <= fb_size FB < 2^26 -> 0 <= n <= 65536 -> fb_newsize FB n < 2^28.
Proof. intros FB n H1 H2. unfold fb_newsize. lia. Qed.

Lemma fb_prep_grow_cap : forall FB n A', fb_cap (fb_prep_grow FB n A') = fb_newsize FB n.
Proof. intros. unfold fb_prep_grow, fb_cap. cbn. lia. Qed.

Lemma fb_prep_small_cap : forall FB n, fb_cap (fb_prep_small FB n) = fb_cap FB.
Proof. intros. unfold fb_prep_small, fb_cap. destruct (fb_prep_inplace FB n); cbn; lia. Qed.

End HCW.
